script:
(function () {
  'use strict';
  // Personal economic recovery: a job loss or pay cut, month by month.
  // Setback (months 1 .. D): any lump sum (severance, final paycheck) is added to savings first.
  //   Each month savings earn APY interest, i = (1 + APY)^(1/12) - 1, and the shortfall
  //   (spending - reduced income) is paid from savings; when savings run out the rest is borrowed
  //   (credit card or loan), which accrues APR / 12 a month. A month with more income than spending
  //   pays down any borrowing first, then adds to savings.
  // Recovery (month D + 1 on): the chosen share of (new income - new spending) goes first to the
  //   borrowing, then to savings until they reach the goal (months of new spending). Recovery is
  //   complete in the first month with no borrowing left and savings at the goal.
  // "Savings alone would last" = whole months the starting savings plus lump sum cover the shortfall
  //   if the setback did not end (interest included).
  // Verified (Node, scratchpad slc5/er.test.js): $10,000 savings, $1,800 shortfall, 0% interest ->
  //   lasts 5 whole months (5.56); a 6-month setback leaves $800 borrowed; at 0% APR and a $900
  //   surplus the debt is cleared in month 1 of recovery and a $25,800 goal is reached after
  //   ceil((25,800 + 800) / 900) = 30 months of recovery; with 3% APY the months-to-last count matches
  //   the closed form n = -ln(1 - B i / S) / ln(1 + i) rounded down; a surplus too small to cover
  //   the interest on the borrowing (or no surplus at all) stops the plan and reports that
  //   recovery is not reached.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var monthName = new Intl.DateTimeFormat('en-US', { month: 'short', year: 'numeric' });
  var MAX_MONTHS = 600;

  function el(id) { return document.getElementById(id); }
  function setText(id, t) { el(id).textContent = t; }
  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function monthlyRate(apy) { return Math.pow(1 + apy, 1 / 12) - 1; }

  // Applies one month: interest, then net cash flow (positive = surplus), returns new state.
  function step(s, net, si, di, goal) {
    var savings = s.savings * (1 + si), debt = s.debt * (1 + di), interest = s.debt * di;
    if (net >= 0) {
      var toDebt = Math.min(net, debt);
      debt -= toDebt; net -= toDebt;
      savings += goal === null ? net : Math.min(net, Math.max(0, goal - savings));
    } else {
      var fromSavings = Math.min(-net, savings);
      savings -= fromSavings;
      debt += -net - fromSavings;
    }
    if (debt < 0.005) debt = 0;
    return { savings: savings, debt: debt, interest: interest };
  }

  function lastMonths(p) {
    var shortfall = p.setbackSpend - p.setbackIncome;
    if (shortfall <= 0) return Infinity;
    var bal = p.savings + p.lump, si = monthlyRate(p.apy), n = 0;
    while (n < MAX_MONTHS) {
      bal = bal * (1 + si) - shortfall;
      if (bal < -1e-9) break;
      n++;
    }
    return n;
  }

  function simulate(p) {
    var si = monthlyRate(p.apy), di = p.apr / 12, goal = p.goalMonths * p.newSpend;
    var s = { savings: p.savings + p.lump, debt: 0 }, rows = [], interest = 0, atReturn = null, paidOff = null, done = null, stuck = false;
    for (var m = 1; m <= MAX_MONTHS; m++) {
      var setback = m <= p.months;
      var income = setback ? p.setbackIncome : p.newIncome, spend = setback ? p.setbackSpend : p.newSpend;
      var net = setback ? income - spend : (income - spend) * p.share;
      var before = s.debt;
      s = step(s, net, si, di, setback ? null : goal);
      interest += s.interest;
      rows.push({ month: m, setback: setback, income: income, spend: spend, savings: s.savings, debt: s.debt });
      if (m === p.months) atReturn = { savings: s.savings, debt: s.debt };
      if (!setback && paidOff === null && s.debt === 0) paidOff = m;
      if (!setback && s.debt === 0 && s.savings >= goal - 0.005) { done = m; break; }
      // Stop once recovery cannot progress: no surplus, or borrowing growing despite payments.
      if (!setback && (net <= 0 || (s.debt > 0 && s.debt >= before - 0.005))) { stuck = true; break; }
    }
    if (p.months === 0) atReturn = { savings: p.savings + p.lump, debt: 0 };
    return { rows: rows, goal: goal, atReturn: atReturn, paidOff: paidOff, done: done, stuck: stuck, interest: interest };
  }

  function clearBody(id) {
    var body = el(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }
  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) { var td = document.createElement('td'); td.textContent = text; tr.appendChild(td); });
    body.appendChild(tr);
  }
  function months(n) {
    if (n === 0) return 'None';
    var y = Math.floor(n / 12), mo = n % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (mo) parts.push(mo + (mo === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }
  function dateAfter(n) {
    var d = new Date();
    return monthName.format(new Date(d.getFullYear(), d.getMonth() + n, 1));
  }

  function update() {
    var p = { setbackIncome: read('erSetbackIncome', true), setbackSpend: read('erSetbackSpend', true), months: read('erMonths'),
              savings: read('erSavings', true), lump: read('erLump', true), newIncome: read('erNewIncome', true),
              newSpend: read('erNewSpend', true), goalMonths: read('erGoalMonths', true), share: read('erShare'),
              apy: read('erApy'), apr: read('erApr') };
    var msg = '';
    if (Object.keys(p).some(function (k) { return isNaN(p[k]); })) msg = 'Fill in every field (amounts can be 0).';
    else if (['setbackIncome', 'setbackSpend', 'savings', 'lump', 'newIncome', 'newSpend'].some(function (k) { return p[k] < 0; }))
      msg = 'Amounts cannot be negative.';
    else if (p.months < 0 || p.months > 120) msg = 'Enter 0 to 120 months until your income returns.';
    else if (p.goalMonths < 0 || p.goalMonths > 24) msg = 'Enter a savings goal of 0 to 24 months of spending.';
    else if (p.share <= 0 || p.share > 100) msg = 'Enter a share of your surplus from 1% to 100%.';
    else if (p.apy < 0 || p.apy > 20 || p.apr < 0 || p.apr > 40) msg = 'Enter a savings APY from 0% to 20% and a borrowing APR from 0% to 40%.';
    var error = el('erError');
    error.hidden = msg === '';
    if (msg) { error.textContent = msg; return; }
    p.months = Math.round(p.months); p.share /= 100; p.apy /= 100; p.apr /= 100;

    var r = simulate(p), lasts = lastMonths(p), shortfall = p.setbackSpend - p.setbackIncome;
    var surplus = p.newIncome - p.newSpend;
    setText('erShortfall', shortfall > 0 ? money.format(shortfall) : 'None');
    setText('erShortfallNote', shortfall > 0 ? 'a month during the setback' : 'Your reduced income covers your spending.');
    setText('erLasts', lasts === Infinity ? 'Indefinitely' : (lasts >= MAX_MONTHS ? 'Over 50 years' : months(lasts) || 'Under a month'));
    setText('erLastsNote', lasts === Infinity ? '' : lasts >= p.months ? 'Long enough to cover the whole setback.' :
      'Runs out before your income returns.');
    setText('erAtReturn', money.format(r.atReturn.savings));
    setText('erBorrowed', money.format(r.atReturn.debt));
    setText('erGoal', money.format(r.goal));
    setText('erSurplus', (surplus < 0 ? '−' : '') + money.format(Math.abs(surplus)));
    setText('erInterest', money.format(r.interest));
    var stuck = el('erStuck');
    if (r.done !== null) {
      var after = r.done - p.months;
      setText('erRecovered', months(r.done) === 'None' ? 'Now' : months(r.done));
      setText('erRecoveredNote', 'from today – around ' + dateAfter(r.done));
      setText('erAfterReturn', months(after));
      setText('erDebtFree', r.atReturn.debt > 0 ? months(r.paidOff - p.months) + ' after income returns' : 'No borrowing needed');
      stuck.hidden = true;
    } else {
      setText('erRecovered', 'Not reached');
      setText('erRecoveredNote', r.stuck ? 'with these figures' : 'within 50 years');
      setText('erInterest', r.stuck && r.atReturn.debt > 0 ? 'Keeps growing' : money.format(r.interest));
      setText('erAfterReturn', '–');
      setText('erDebtFree', r.paidOff !== null ? months(r.paidOff - p.months) + ' after income returns' : 'Not reached');
      stuck.hidden = false;
      stuck.textContent = surplus <= 0 ? 'Your spending after the setback is at or above your new income, so nothing is left to rebuild with. Lower your spending or raise your income to see a recovery plan.' :
        'The amount you put toward recovery each month is too small to clear the borrowing and reach your savings goal.';
    }

    var body = clearBody('erTable');
    r.rows.forEach(function (row) {
      addRow(body, [String(row.month), row.setback ? 'Setback' : 'Recovery', money.format(row.income), money.format(row.spend),
                    money.format(row.savings), money.format(row.debt)]);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('erForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
